footer li { display: grid; gap: 0.1rem; }
footer button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
  border-bottom: 2px solid transparent;
  padding: 0.2rem 0;
  margin: 0;
  display: grid;
  gap: 0.1rem;
  text-align: left;
  cursor: pointer;
  transition: border-color 0.2s, color 0.2s;
}
footer button:hover span,
footer button[aria-pressed="true"] span { color: var(--accent); }
footer button[aria-pressed="true"] { border-bottom-color: var(--accent); }
footer button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 4px;
  border-radius: 2px;
}

// Tap a greeting to swap the headline word; tap it again to go back to "Hello".
const wordEl = document.querySelector(".word");
const langButtons = Array.from(document.querySelectorAll("footer button"));

function setWord(text, lang) {
  wordEl.setAttribute("aria-label", text);
  wordEl.lang = lang;
  const parts = window.Intl && Intl.Segmenter
    ? Array.from(new Intl.Segmenter(lang, { granularity: "grapheme" }).segment(text), (s) => s.segment)
    : [text];
  wordEl.replaceChildren(...parts.map((ch, i) => {
    const s = document.createElement("span");
    s.textContent = ch;
    s.style.setProperty("--i", i);
    s.setAttribute("aria-hidden", "true");
    return s;
  }));
}

langButtons.forEach((btn) => {
  btn.addEventListener("click", () => {
    const turningOn = btn.getAttribute("aria-pressed") !== "true";
    langButtons.forEach((b) => b.setAttribute("aria-pressed", "false"));
    if (turningOn) {
      btn.setAttribute("aria-pressed", "true");
      setWord(btn.querySelector("span").textContent, btn.lang);
    } else {
      setWord("Hello", "en");
    }
  });
});

